mapper.select:
SELECT SD.DEVICE_NAME, SA.AREA_NAME, SDT.GENERAL AS PLATE, SDT.DEVICE_CODE, SDT.CARD_NO, SDT.START_TIME, SDT.CREATE_TIME, SDT.OVER_TIME FROM SMT_TASK_DOWN_RECORD SDT LEFT JOIN ( SELECT SLA.ID AS VEHICLE_ID, SLA.DRIVER_NAME AS PERSON_NAME FROM SMT_LOGISTICS_APPOINTMENT SLA UNION ALL SELECT SV.ID AS VEHICLE_ID, SV.VISITOR_NAME AS PERSON_NAME FROM SMT_VISITOR SV UNION ALL SELECT SNS.VEHICLE_ID AS VEHICLE_ID, SNS."NAME" AS PERSON_NAME FROM SMT_NOT_STAFF SNS UNION ALL SELECT SVS.VEHICLE_ID AS VEHICLE_ID, SS."NAME" AS PERSON_NAME FROM SMT_VEHICLE_STAFF SVS LEFT JOIN SMT_STAFF SS ON SVS.STAFF_ID = SS."ID" ) PERSON ON PERSON.VEHICLE_ID = SDT.CARD_NO LEFT JOIN SMT_DEVICE SD ON SD.ID = SDT.DEVICE_CODE LEFT JOIN SMT_DEVICE_AREA SDA ON SDA.DEVICE_ID = SDT.DEVICE_CODE LEFT JOIN SMT_AREA SA ON SA.ID = SDA.AREA_ID WHERE SDT.DEVICE_TYPE = 2 AND SDT.ACTION = 1
AND SD.DEVICE_NAME LIKE CONCAT('%', CONCAT(#{query.deviceName}, '%'))
AND SDT.GENERAL LIKE CONCAT('%', CONCAT(#{query.plate}, '%'))
AND SDA.AREA_ID IN ( SELECT SA."ID" FROM SMT_AREA SA
AND SA.PARK_ID = #{query.parkId}
AND SA.PID = #{query.parAreaId}
AND SA."ID" = #{query.areaId}
)
AND SD.PARK_ID IN
#{tempId}
ORDER BY SDT.CREATE_TIME DESC
